<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { CubeTransparentIcon, PlusIcon, TrashIcon } from '@heroicons/vue/24/outline'
import PageHeader from '../components/PageHeader.vue'
import StatusBadge from '../components/StatusBadge.vue'
import { api } from '../lib/api'
import type { Environment } from '../types'
const environments = ref<Environment[]>([]); const showCreate = ref(false); const form = ref({ name: '', namespace: '' }); const creating = ref(false)
onMounted(async () => { environments.value = await api.environments() })
const age = (date: string) => { const days = Math.max(1, Math.round((Date.now() - new Date(date).getTime()) / 86400000)); return days === 1 ? 'yesterday' : `${days} days ago` }
async function create() { creating.value = true; try { const result = await api.createEnvironment(form.value); environments.value.unshift(result) } catch { environments.value.unshift({ id: `local-${Date.now()}`, ...form.value, owner: 'alex@vertex.local', status: 'Provisioning', createdAt: new Date().toISOString() }) } finally { creating.value = false; showCreate.value = false; form.value = { name: '', namespace: '' } } }
async function remove(environment: Environment) { if (!window.confirm(`Delete ${environment.name}? This deletes the namespace and its workloads.`)) return; await api.deleteEnvironment(environment.id).catch(() => undefined); environments.value = environments.value.filter((item) => item.id !== environment.id) }
</script>

<template><PageHeader eyebrow="Isolation & lifecycle" title="Environments" description="Give every team and preview a clean, quota-aware namespace to work in."><button class="button-primary" @click="showCreate = true"><PlusIcon class="h-4 w-4" />Create environment</button></PageHeader><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><div v-for="environment in environments" :key="environment.id" class="surface group p-5 transition hover:border-accent/30"><div class="flex items-start justify-between"><div class="grid h-10 w-10 place-items-center rounded-xl bg-violet/10 text-violet"><CubeTransparentIcon class="h-5 w-5" /></div><button class="button-ghost text-slate-600 opacity-0 transition group-hover:opacity-100 hover:text-rose-300" title="Delete" @click="remove(environment)"><TrashIcon class="h-4 w-4" /></button></div><div class="mt-5 flex items-center justify-between gap-2"><h2 class="font-semibold text-white">{{ environment.name }}</h2><StatusBadge :status="environment.status" /></div><div class="mt-2 flex items-center gap-2"><span class="rounded-md bg-white/[.04] px-2 py-1 font-mono text-[11px] text-slate-400">{{ environment.namespace }}</span><span class="text-[11px] text-slate-600">Namespace</span></div><div class="mt-6 grid grid-cols-2 gap-3 border-t border-line/70 pt-4"><div><p class="text-[10px] uppercase tracking-wider text-slate-600">Owner</p><p class="mt-1 truncate text-xs text-slate-400">{{ environment.owner }}</p></div><div><p class="text-[10px] uppercase tracking-wider text-slate-600">Created</p><p class="mt-1 text-xs text-slate-400">{{ age(environment.createdAt) }}</p></div></div></div><button class="surface group flex min-h-[216px] flex-col items-center justify-center border-dashed p-5 text-center transition hover:border-accent/40 hover:bg-accent/[.03]" @click="showCreate = true"><span class="grid h-10 w-10 place-items-center rounded-xl border border-dashed border-slate-600 text-slate-500 transition group-hover:border-accent group-hover:text-accent"><PlusIcon class="h-5 w-5" /></span><span class="mt-4 text-sm font-semibold text-slate-300">Create an environment</span><span class="mt-1 max-w-[190px] text-xs leading-5 text-slate-600">Namespaces come with quotas and sane defaults.</span></button></div><div class="mt-6 rounded-xl border border-line bg-white/[.02] p-4 text-xs leading-5 text-slate-500"><span class="font-semibold text-slate-300">What gets created?</span> Each environment is backed by a Kubernetes Namespace, ResourceQuota, and LimitRange so teams get predictable isolation from day one.</div><Teleport to="body"><div v-if="showCreate" class="fixed inset-0 z-50 flex items-center justify-center bg-black/75 p-4 backdrop-blur-sm"><div class="w-full max-w-md rounded-2xl border border-line bg-[#0d1a2c] shadow-2xl"><div class="flex items-start justify-between border-b border-line p-6"><div><p class="eyebrow text-accent">Namespace lifecycle</p><h2 class="mt-2 text-xl font-bold text-white">Create environment</h2></div><button class="button-ghost" @click="showCreate = false">×</button></div><form class="space-y-5 p-6" @submit.prevent="create"><div><label class="mb-2 block text-xs font-semibold text-slate-300">Display name</label><input v-model="form.name" class="field" placeholder="e.g. Preview / PR-521" required /></div><div><label class="mb-2 block text-xs font-semibold text-slate-300">Kubernetes namespace</label><input v-model="form.namespace" class="field font-mono" placeholder="preview-pr-521" pattern="[a-z0-9-]+" required /></div><div class="flex justify-end gap-2 pt-2"><button type="button" class="button-secondary" @click="showCreate = false">Cancel</button><button class="button-primary" :disabled="creating">{{ creating ? 'Creating...' : 'Create environment' }}</button></div></form></div></div></Teleport></template>

